/**
 * ======================================================================
 * 【基本说明】：
 * 本文件是MobileIMSDK-Web版服务端SDK的核心入口，以回调的方式向外暴露各种事件通知、实用方法等。
 *
 * 【使用方法】：详见Demo主文件www.js的代码实现即可
 *   // MobileIMSDK-Web版的SDK主入口
 *   var imServerSDK = require('../j_core/im-server-sdk');
 *   // 创建MobileIMSDK-Web版服务端的服务
 *   imServerSDK.createServer(server);
 *   // 设置连接认证回调
 *   imServerSDK.setCallBack_checkAuthToken(fn);
 *   // 设置个人认证后信息的处理回调
 *   imServerSDK.setCallBack_authedInfo(fn);
 *   // 设置用户上线回调
 *   imServerSDK.setCallBack_userOnline(fn);
 *   // 设置用户离线回调
 *   imServerSDK.setCallBack_userOffline(fn);
 *   // 设置C2S消息回调
 *   imServerSDK.setCallBack_receivedC2SMessage(fn);
 *   // 设置C2C消息回调
 *   imServerSDK.setCallBack_transferedC2CMessage(fn);
 *   // 设置离线消息处理回调
 *   imServerSDK.setCallBack_processC2COfflineMessage(fn);
 *
 * 【补充说明】：
 * 原本是希望像其它OOP语言一样，写一个IMServerSDK的类，通过module.export=IMServerSDK
 * 暴露给外部来使用，但因为Socket.io的“require('socket.io')(server)”这种方法，需要传参
 * 'server'，而在外部调用时通过“var imServerSDK = require('../j_core/im-server-sdk')(server);”
 * 的结果是imServerSDK确是undefine！！这太诡异了，而外部换成普通的new IMServerSDK(server)时，又会导致IMServerSDK
 * 内部的socketio对象找不到on、use这些函数（报not a function）！目前干脆换成目前这种传统的JS代码方式写，
 * 这样更顺手，所以不应硬生生地把OOP理论带入到Nodejs，因为JS语言天生就是为了简单，或许回归本真才是最佳实践！
 * ======================================================================
 */

var SendUtilsLocal = require('./send-util-local');
var SendUtilsGlobal = require('./send-util-global');
var config = require('../j_conf/config');
var logger = require('../j_conf/log').logger;
var ErrorFactory = require('./error-factory');
var UserProcessorClass = require('./user-processor');
var ProtocalType = require('./protocal-type');
var ProtocalFactory = require('./protocal-factory');

var MBQoS4SendDaemonClass = require('./qos_send');
var MBQoS4ReciveDaemonClass = require('./qos_recieve');

// 内部变量：MQ中间件服务提供者（用于异构消息的处理）
var imMQProvider = config.im_bridge_enabled? require('./im-mq-provider'): null;
// 内部变量：在线列表
var userProcessor = new UserProcessorClass();
//
var mbQoS4SendDaemon = new MBQoS4SendDaemonClass();
//
var mbQoS4ReciveDaemon = new MBQoS4ReciveDaemonClass();
// 内部变量：socket.io的服务端连接实xx例
var socketio = null;

// 以下回调方法由sdk的应用层开发者设置哦
var callBack_checkAuthToken = null;
var callBack_userOnline = null;
var callBack_userOffline = null;
var callBack_receivedC2SMessage = null;       // 此回调相当于APP的IM服务端回调方法：onTransBuffer_CallBack
var callBack_transferedC2CMessage = null;     // 此回调相当于APP的IM服务端回调方法：onTransBuffer_C2C_CallBack
var callBack_processC2COfflineMessage = null;
var callBack_authedInfo = null;
var callback_onMessagesLost= null;
var callback_onMessagesBeReceived = null;


// 内部方法：初始化整个服务端IM的SDK
function _init(){

    /** -----------------------------------------------------------------------------------
     * 启动MQ中间件服务（开启桥接跨服消息的处理）.
     */

    // 需要与APP版的互通
    if (config.im_bridge_enabled) {

        // 设置MQ桥接消息回调：以下回调函数将在nodejs端的MQProvider中当收到MQ的消息时进行回调，应用层通过此回调来进行消息转发处理
        // 本回调的返回值说明：true表示此消息正确处理完成，false表示未成功处理（MQ会将原消息重放回队列以便下次再取到）。
        imMQProvider.setCallBack_forWork(function (p) {
            try {
                // 如果nodejs端通过桥接（收到的是APP端发过来的消息）收到的消息不为空则尝试在本nodejs机器发送（给用户）
                if (p) {
                    logger.debug('[IMSDK-MQ↓]【桥接收】callBack_forWork回调中收到Protocal对象：[%s], 马上通过本机的WebIM发送之！'
                        , JSON.stringify(p));

                    // 发送消息（此方法内的sendData实际上会通过回调处理在线和不在线的情况，只管调用就是了）
                    // ## Bug fixed by js 20160922: 之前错误地把p.to写成了p.toLocalString而导致收消息时
                    // ## - 出现"RabbitMQ Error Code 504"(原因是错误地代码使得sendProtocalForOnlineOrOffline发生异常，
                    // ## - 因没有try catch而蔓延至MQProvider里的处理代码)!
                    //sendDataLocal4OnlineOrOffline(userProcessor.getSession(p.to), p);
                    // 检验是否是消息合并发送
                    if(p.dataContent  && JSON.parse(p.dataContent).cy - 2 == 0){
                        const  tos  = p.to ? p.to.split(','):[];
                        const onList = tos.filter(item=> {
                                const socket = userProcessor.getSession(item);
                                return (socket && socket.connected)
                        });
                        if(onList && onList.length > 0){
                            onList.forEach(item=>{
                                sendDataLocal4OnlineOrOffline(null, {...p,to:item}, null);
                            })
                        }
                    }else{
                        sendDataLocal4OnlineOrOffline(null, p, null);
                    }
                   
                    // //多个
                    // if(tos.length > 1){
                    // //    const offList = tos.filter(item=> {
                    // //         const socket = userProcessor.getSession(item);
                    // //         return !(socket && socket.connected)
                    // //    });
                    //     const onList = tos.filter(item=> {
                    //     const socket = userProcessor.getSession(item);
                    //         return (socket && socket.connected)
                    //      });
                   
                    // //    // 有离线数据，合并一起发送 
                    // //    if(offList && offList.length > 0){
                    // //         const newp = {...p,to:offList.join(',')};
                    // //         if(callBack_processC2COfflineMessage){
                    // //             callBack_processC2COfflineMessage(newp)
                    // //         }
                    // //    }
                    //    // 在线
                    //    if(onList && onList.length > 0){
                    //         onList.forEach(item=>{
                    //             sendDataLocal4OnlineOrOffline(null, {...p,to:item}, null);
                    //         })
                    //    }
                    
                    // }else{
                    //     const socket = userProcessor.getSession(p.to)
                    //     if(socket && socket.connected){
                    //         sendDataLocal4OnlineOrOffline(null, p, null);// 因为桥接消息是由服务端代码，所以第一个参数（发送者的socket引用）自然填null
                    //     }
                    // }
                    // sendDataLocal4OnlineOrOffline(null, p, null);// 因为桥接消息是由服务端代码，所以第一个参数（发送者的socket引用）自然填null
                    return true;
                }
                else {
                    logger.error('[IMSDK-MQ↓]【桥接收】callBack_forWork回调中收到无效的Protocal对象：%s，【本条处理没有继续】', JSON.stringify(p));
                    //return false;
                    return true;// 【注意】尽量不要返回false，不然消息被放回队列后容易死循环，出错作好记录备查即可！
                }
            }
            catch (e) {
                logger.error('[IMSDK-MQ↓]【桥接收】callBack_forWork回调中出错了，消息内容：[%s]，错误原因：[%s]【本条处理没有继续】'
                    , JSON.stringify(p), JSON.stringify(e));
                return true;// 【注意】尽量不要返回false，不然消息被放回队列后容易死循环，出错作好记录备查即可！
            }

        });
        // 启动MQ中件件服务
        imMQProvider.start();

        logger.info("[IMSDK] 配置项：已开启与MobileIMSDK APP的互通 √ ！");
    }
    else{
        logger.info("[IMSDK] 配置项：未开启与MobileIMSDK APP的互通 × ！");
    }


    /** -----------------------------------------------------------------------------------
     * 处理WebSocket认证相关的事项.
     */

    socketio.use(function (socket, next) {
        //var token = socket.request.query.token;
        var token = socket.handshake.query.token;
        logger.debug('[IMSDK] 客户端正在发起连接并提交了认证token=%s', token);
        var loginInfo = JSON.parse(token);

        // SDK的持有者是否设置了认证方法
        if(callBack_checkAuthToken) {
            // 对客户端的连接进行合法身份认证和检查
            callBack_checkAuthToken(loginInfo, function (err, authorized) {
                // 认证实败
                if (err || !authorized) {
                    // 将未认证情况通过error事件传回给客户端
                    next(new Error(JSON.stringify(ErrorFactory.CodeUnauthed)));

                    // If the socket didn't authenticate, disconnect it
                    // 补充：因Socket.io的底层网络机制，客户端此时不能主动关闭连接，不然服务
                    // 端无法触发它的disconnect事件（客户端事件也会不正常）。而服务端也不要
                    // 立即关闭，延迟几秒以备客户端处理完上面的Error认证事件
                    SendUtilsLocal.lazyCloseSocket(socket, '[IMSDK] 客户端：' + socket.id + ' 因连接未获认证，马上关闭之... ')
                }
                // 认证成功
                else {
                    // 将用户id作为一个socket的合法认证身份先给存起来（换句话：没有userId的socket肯定是非法的）
                    socket.userId = loginInfo.loginUserId;
                    // 将用户认证完的个人信息存储起来备用 - add by js 20161027
                    socket.authedinfo = callBack_authedInfo(loginInfo);

                    logger.debug('[IMSDK] 新用户 %s (skt.id=%s)已经上线成功！', socket.userId, socket.id);

                    // 将认证成功的情况通过error事件发射回客户端
                    next(new Error(JSON.stringify(ErrorFactory.CodeAuthed)));
                    // 将用户信息放入到在线列表中（理论上：每一个存放在在线列表中的session都对应了user_id）
                    userProcessor.putUser(socket.userId, socket);

                    // @@ 用户上线回调或上通通知！！
                    if(callBack_userOnline) {
                        callBack_userOnline(socket.userId, socket);
                    }
                }

                // 没有此行代码，上面即使执行了socket.disconnet也同样不会停止客户端的自动重连，
                // 而且不会真正触发disconnect事件，估计跟底层的事件链有关系，具体原因理空再深究
                next();
            });
        }
        else{
            logger.error('[IMSDK] 【错误】没有设置用户认证函数：callBack_checkAuthToken！！！');
        }
    });


    /** -----------------------------------------------------------------------------------
     * 处理WebSocket和聊天相关的事件.
     */

    socketio.on('connection', function (socket) {
        logger.debug('[IMSDK] [E]客户端：%s 已经建立连接！', socket.id);

        // 客户端一对一聊天的通用数据发送事件
        socket.on(ProtocalType.C_IMEVT_COMMON$DATA, function (p) {
            logger.debug('[IMSDK] [E]服务端收到本客户端：%s(name=%s) C_IMEVT_COMMON$DATA 事件，即将送给指定的人(%s) 。。。'
                , socket.id, socket.userId, JSON.stringify(p));

            // 只有认证了的socket才允许
            if (socket.userId) {

                // 【C2S数据】客户端发给服务端的消息
                if('0'== p.to) {
                    processC2SMessage(socket, p);

                    // logger.debug('[IMSDK] >> [E]【C2S】服务端收到本客户端：%s(name=%s) C_IMEVT_COMMON$DATA 事件，此条是C2S消息！', socket.id, socket.userId);
                    //
                    // // 客户端直发服务端（而不是发给另一客户端）的正常数据包则回一个C2S模式的质量保证模式下的应答包
                    // if(p.QoS) {
                    //     var hasRecieved = mbQoS4ReciveDaemon.hasRecieved(p.fp);
                    //
                    //     // ## Bug FIX: 20170215 by jackjiang - 解决了不能触发回调onTransBuffer_CallBack的问题
                    //     //------------------------------------------------------------------------------ [2]代码与[1]处相同的哦 S
                    //     // 【【QoS机制2/4步：将收到的包存入QoS接收方暂存队列中（用于防QoS消息重复）】】
                    //     // @see 客户端LocalUDPDataReciever中的第1/4和第4/4步相关处理
                    //     mbQoS4ReciveDaemon.addRecieved(p);
                    //     // 【【QoS机制3/4步：回应答包】】
                    //     // @see 客户端LocalUDPDataReciever中的第1/4和第4/4步相关处理给发送者回一个“收到”应答包(发送C2S模式的应答包)
                    //     replyRecievedBack(socket, p, null);
                    //     //------------------------------------------------------------------------------ [2]代码与[1]处相同的哦 E
                    //
                    //     // 已经存在于已接收列表中（及意味着可能是之前发给对方的应答包因网络或其它情况丢了，对方又因QoS机制重新发过来了）
                    //     if(hasRecieved) {
                    //         logger.debug("[IMSDK] >> [E]【QoS机制】"+p.fp+"因已经存在于发送列表中，这是重复包，本次忽略通知业务处理层（只需要回复ACK就行了）！");
                    //         return;
                    //     }
                    // }
                    //
                    // // @@ 业务层或者利用回调来处理C2S消息！！
                    // if(callBack_receivedC2SMessage){
                    //     callBack_receivedC2SMessage(p, socket);
                    // }
                }
                // 【C2C数据】客户端发给客户端的消息
                else{
                    // sendDataGlobal(socket, p, callBack_processC2COfflineMessage);
                    processC2CMessage(socket, p);
                }
            }
            else{
                logger.error('[IMSDK] [E]本客户端：%s(name=%s) C_IMEVT_COMMON$DATA 事件(p=%s)，奇怪的是本socket没有认证！！！非法！！'
                    , socket.id, socket.userId, JSON.stringify(p));
                // 对非法会话的处置
                replyDataForUnlogined(socket);

                // // 将非法连接被拒绝服务的消息反馈给此连接客户端（以备它在ui上给用户以友好的反馈）,
                // // to_user_id此时就没有意义了，因为此处服务端要返回消息原因就是它是不存在user_id的非法连接
                // var ok = SendUtilsLocal.sendData1(socket, ProtocalFactory.createIllegalResponse('illegal_no_userid!'), null);
                // // 同时关掉它的网络连接
                // // 补充：因Socket.io的底层网络机制，客户端此时不能主动关闭连接，不然服务
                // // 端无法触发它的disconnect事件（客户端事件也会不正常）。而服务端也不要
                // // 立即关闭，延迟几秒以备客户端处理完上面的消息事件
                // SendUtilsLocal.lazyCloseSocket(socket, '[IMSDK] [E]【注意】socket.id='
                //     +socket.id+'是非法连接，已被拒绝服务并被关闭了socket连接！(ok='+ok+')');
            }
        });

        // 客户端与客户端、客户端与服务端之间的ACK应答事件
        socket.on(ProtocalType.S_IMEVT_RECIVED, function (p) {
            logger.debug("[IMSDK] [E]【QoS机制_S2C】收到客户端%s(name=%s) 的ACK应答包.", socket.id, socket.userId);

            // 只有认证了的socket才允许
            if (socket.userId) {

                //## 与MobileIMSDK的APP版框架一样，所有由服务端直发（s2c模式）或转发（c2c模式）的消息，
                //## 客户端发回来的应答包只需要由服务端接收并处理，取消了之前c2c模式下，客户端的ACK应答
                //## 包需要回给客户端发送者（这个逻辑在极端情况下，会受发送端网络的影响，而导致体验不佳。）

                // 应答包的消息内容即为之前收到包的指纹id
                var theFingerPrint = p.dataContent;
                logger.debug("[IMSDK] [E]【QoS机制_S2C】收到接收者%s回过来的指纹为%s的应答包.", p.from, theFingerPrint);

                // 将收到的应答事件通知事件处理者
                if(callback_onMessagesBeReceived)
                    callback_onMessagesBeReceived(theFingerPrint);

                // 【【S2C模式下的QoS机制4/4步：收到应答包时将包从发送QoS队列中删除】】
                mbQoS4SendDaemon.remove(theFingerPrint);
            }
            else{
                logger.error('[IMSDK] [E]【QoS机制_S2C】本客户端：%s(name=%s) S_IMEVT_RECIVED 事件，奇怪的是本socket没有认证！！！非法！！', socket.id, socket.userId);
                // 对非法会话的处置
                replyDataForUnlogined(socket);
            }
        });

        // when the user disconnects.. perform this
        socket.on('disconnect', function () {
            // userId不为空即表示是成功登陆的用户，否则是没有认证成功的用户，就不需要通知其它人了
            if (socket.userId) {
                // 将此用户从在线列表中移除
                var ok = userProcessor.removeUser(socket.userId);
                logger.debug('[IMSDK] [E]用户 %s (skt.id=%s) 连接已断开，是否成功从在线列表中移除？%s'
                    , socket.userId, socket.id, ok);

                // @@ 用户离线回调或离通通知！！
                if(callBack_userOffline){
                    callBack_userOffline(socket.userId, socket);
                }
            }
            else {
                logger.debug('[IMSDK] [E]skt.id=%s 连接已断开（该连接中没有认证信息，可能来自未认证成功要关闭的连接！）'
                    , socket.id);
            }

            logger.debug('[IMSDK] [E]客户端：%s 已断开连接(socket.name=%s)，【END】', socket.id, socket.userId);
        });
    });


    /** -----------------------------------------------------------------------------------
     * QoS机制定时器启动.
     */

    // ** 【4】启动服务端对S2C模式的QoS机制下的防重复检查线程
    mbQoS4ReciveDaemon.startup(true);
    // ** 【5】启动服务端对S2C模式下QoS机制的丢包重传和离线通知线程
    mbQoS4SendDaemon.startup(true);
}

/**
 * 处理C2C（client to client）类消息（即客户端发给客户端的普通聊天消息）。
 *
 * @param bridgeProcessor
 * @param session
 * @param pFromClient
 * @param remoteAddress
 * @throws Exception
 */
function processC2CMessage(socket, p){
    sendDataGlobal_c2C(socket, p, callBack_processC2COfflineMessage);
}

/**
 * 处理C2S（client to server）类消息（即客户端发给服务端的指令类消息）。
 *
 * @param session
 * @param pFromClient
 * @param remoteAddress
 * @throws Exception
 */
function processC2SMessage(socket, p){
    logger.debug('[IMSDK] [E]【C2S】服务端收到本客户端：%s(name=%s) C_IMEVT_COMMON$DATA 事件，此条是C2S消息！', socket.id, socket.userId);

    // 客户端直发服务端（而不是发给另一客户端）的正常数据包则回一个C2S模式的质量保证模式下的应答包
    if(p.QoS) {
        var hasRecieved = mbQoS4ReciveDaemon.hasRecieved(p.fp);

        // ## Bug FIX: 20170215 by jackjiang - 解决了不能触发回调onTransBuffer_CallBack的问题
        //------------------------------------------------------------------------------ [2]代码与[1]处相同的哦 S
        // 【【QoS机制2/4步：将收到的包存入QoS接收方暂存队列中（用于防QoS消息重复）】】
        // @see 客户端LocalUDPDataReciever中的第1/4和第4/4步相关处理
        mbQoS4ReciveDaemon.addRecieved(p);
        // 【【QoS机制3/4步：回应答包】】
        // @see 客户端LocalUDPDataReciever中的第1/4和第4/4步相关处理给发送者回一个“收到”应答包(发送C2S模式的应答包)
        replyRecievedBack(socket, p, null);
        //------------------------------------------------------------------------------ [2]代码与[1]处相同的哦 E

        // 已经存在于已接收列表中（及意味着可能是之前发给对方的应答包因网络或其它情况丢了，对方又因QoS机制重新发过来了）
        if(hasRecieved) {
            logger.debug("[IMSDK] [E]【QoS机制】"+p.fp+"因已经存在于发送列表中，这是重复包，本次忽略通知业务处理层（只需要回复ACK就行了）！");
            return;
        }
    }

    // @@ 业务层或者利用回调来处理C2S消息！！
    if(callBack_receivedC2SMessage){
        callBack_receivedC2SMessage(p, socket);
    }
}

/**
 * 当服务端检测到用户尚未登陆（或登陆会话已失效时）由服务端回复给
 * 客户端的消息。
 * <p>
 * <font color="red">本方法将由MobileIMSDK框架内部算法按需调用，目前不建议也不需要开发者调用。</font>
 *
 * @param socket
 */
function replyDataForUnlogined(socket) {

    // 将非法连接被拒绝服务的消息反馈给此连接客户端（以备它在ui上给用户以友好的反馈）,
    // to_user_id此时就没有意义了，因为此处服务端要返回消息原因就是它是不存在user_id的非法连接
    var ok = SendUtilsLocal.sendData1(socket, ProtocalFactory.createIllegalResponse('illegal_no_userid!'), null);
    // 同时关掉它的网络连接
    // 补充：因Socket.io的底层网络机制，客户端此时不能主动关闭连接，不然服务
    // 端无法触发它的disconnect事件（客户端事件也会不正常）。而服务端也不要
    // 立即关闭，延迟几秒以备客户端处理完上面的消息事件
    SendUtilsLocal.lazyCloseSocket(socket, '[IMSDK] [E]【注意】socket.id='
        +socket.id+'是非法连接，已被拒绝服务并被关闭了socket连接！(ok='+ok+')');
}

/**
 * 服务端回复应答包（给客户端发送方）。前提是客户发送的消息包中的字段QoS=true，否则本方法什么也不做。
 * <p>
 * <b>何为应答包？</b><br>
 * 应答包是MobileIMSDK框架中的QoS消息送达保证机制的一部分，即为了保证消息必达（QoS=true时），由客户端发出的
 * 消息，只要到达服务端（c2c或c2s路径的消息），服务端就会返回ACK应答包，表示告诉客户端“消息已被收到”（实际上
 * 这条消息的下半程，将由服务端来继续处理，但客户端就不需要具体知道后续的环节了。）
 * <p>
 * <font color="red">本方法将由MobileIMSDK框架内部算法按需调用，目前不建议也不需要开发者调用。</font>
 *
 * @param socket 被回复的会话
 * @param pFromClient {Protocal} 客户端发过来的数据包，本方法将据此包中的from、to、fp属性进行回复
 * @param fnProcessOfflineMessage {function} 因netty的异步化特征，发送数据在API层也是异步的
 * @throws Exception 当发送数据出错时将抛出本异常
 * @see #sendData(io.netty.channel.Channel, Protocal, MBObserver)
 */
function replyRecievedBack(socket, pFromClient, fnProcessOfflineMessage) {
    if(pFromClient.QoS && pFromClient.fp != null) {
        var receivedBackP = ProtocalFactory.createRecivedBack(pFromClient.to, pFromClient.from, pFromClient.fp, false);
        var ok = SendUtilsLocal.sendData1(socket, receivedBackP, fnProcessOfflineMessage);
        logger.debug("[IMSDK] [E]【QoS_应答_C2S】向"+pFromClient.from+"发送"+pFromClient.fp +"的应答包成功了?（ok="+ok+"）,from="+pFromClient.to+".");
        return ok;
    }
    else {
        logger.warn("[IMSDK] [E]收到%s发过来需要QoS的包，但它的指纹码却为null！无法发伪应答包哦！",  pFromClient.from);
    }
}

/**
 * 一个发送（仅限于本机用户）消息的方便方法（用户不在线时的处理，会参sendData方法内通过回调，本方法只管调用就行了）
 * 提炼出本方法的目的，是希望本机用户消息的发送和work桥接收到的消息的代发代码统一，便于维护.
 * <p>
 * 本方法的消接收者仅限且必须限于本机范围内，是否需要作为MQ桥接消息不在本方法内考虑（应由本方法的外层方法去考虑），
 * 否则将导致桥接消息的发送混乱。
 *
 * @param senderSocket 消息发送者的socket（当为桥接消息由服务端代发时，本socket参数为null），本参数主要为了log输出
 * @param p 要发送给对方的消息包（接收者的socket将会通过p.to 在 userProcessor中的用户列表找到）
 * @param arg_callBack_processC2COfflineMessage 非必须参数，用于指定消息没有在线发送成功时的离线消息回调处理，如果本参数为空则
 * 函数内将使用默认的callBack_processC2COfflineMessage作为离线消息的回调处理函数。【提示】：有些消息如果您不希望被离线存储（比如下线通知），
 * 则可以通过自定义本离线回调（比如让你的自写义回调只打出Log而不使用默认回调里的持久化到数据库等）来实现就行了！
 * @return true表示发出完成
 */
// 【友情提示】：
// 如果是被转发的桥接消息的情况，而您不希望这个消息被离线存储（只希望接收者在线的话就发，不在线就不发）时，
// 您可以考虑将arg_callBack_processC2COfflineMessage参数传入您自定义的函数（比如让你的自写义回调只打出
// Log而不使用默认回调里的持久化到数据库等），那么这样也就实现了不需要将某类不必要的消息持久化了，比如APP那
// 边发过来的下线通知，这种通知只是实时用意义，如果接收者不在线还要离线存它有何意义呢？！
function sendDataLocal4OnlineOrOffline(senderSocket, p, arg_callBack_processC2COfflineMessage){

    // ###### Bug FIX: 20170918 START
    // 如果回调函数arg_callBack_processC2COfflineMessage为空，则使用系统默认的
    // callBack_processC2COfflineMessage作为回调函数，否则使用用户自定义的回调函数
    if(arg_callBack_processC2COfflineMessage){
        // do nothing
    }
    else {
        arg_callBack_processC2COfflineMessage = callBack_processC2COfflineMessage;
    }
    // ###### Bug FIX: 20170918 END

    var ok = SendUtilsLocal.sendData2(userProcessor, p, arg_callBack_processC2COfflineMessage);
    // 以下代码主要为了Log输出
    if (senderSocket) {
        logger.debug('[IMSDK] [E]本客户端：%s(name=%s) 的 C_IMEVT_COMMON$DATA 事件，实时发送给指定的人(%s) 了吗？【%d】'
            , senderSocket.id, senderSocket.userId, p.to, ok);
    }
    else {
        logger.debug('[IMSDK] [E]【C2S消息】 C_IMEVT_COMMON$DATA 事件，实时发送给指定的人(%s) 了吗？【%d】'
            ,  p.to, ok);
    }

    if(ok){
        // @@ C2C消息发送成功后的回调实现（此回调的作为像APP的IM服务端端一样通常用作用户行为和聊
        //    天内容抓取之用）本回调的作用参考APP的IM服务端的onTransBuffer_C2C_CallBack(..)
        if(callBack_transferedC2CMessage){
            callBack_transferedC2CMessage(p,true);
        }
    }
    // * 离线回调将在 SendUtilsLocal.sendData2 里被调用，以下代码就不需要了！
    //else{
    //    // @@ C2C消息发送失败后的回调实现！（应用层可能需要做离线消息处理！）
    //    if(callBack_processC2COfflineMessage){
    //        callBack_processC2COfflineMessage(p);
    //    }
    //}

    return ok;
}

/**
 * 用方法用于服务端作为中转发送C2C类型的数据之用，此方法封装了服务端中转发送
 * C2C消息的所有逻辑（包括当接收者不在本机在线列表时的桥接处理、离线处理逻辑等）。
 * <p>
 * <b>注意：</b>本方法不应由服务端的应用层调用，仅限MobileIMSDK-Web框架内部使用。
 *
 * @param socket 消息发起者的socket句柄（而非接收者哦），此句柄在方法中主要用于log信息的提取。
 * 当服务端主动发起消息（即S2C模式的消息，而非C2C）时本socket参数请填null就行了
 * @param p
 * @param arg_callBack_processC2COfflineMessage 非必须参数，用于指定消息没有在线发送成功时的离线消息回调处理，如果本参数为空则
 * 函数内将使用默认的callBack_processC2COfflineMessage作为离线消息的回调处理函数。【提示】：有些消息如果您不希望被离线存储（比如下线通知），
 * 则可以通过自定义本离线回调（比如让你的自写义回调只打出Log而不使用默认回调里的持久化到数据库等）来实现就行了！
 */
function sendDataGlobal_c2C(socket, p, arg_callBack_processC2COfflineMessage){

    // ###### Bug FIX: 20170918 START
    // 如果回调函数arg_callBack_processC2COfflineMessage为空，则使用系统默认的
    // callBack_processC2COfflineMessage作为回调函数，否则使用用户自定义的回调函数
    if(arg_callBack_processC2COfflineMessage){
        // do nothing
    }
    else {
        arg_callBack_processC2COfflineMessage = callBack_processC2COfflineMessage;
    }
    // ###### Bug FIX: 20170918 END

    // ** 【已启用与APP端的互通 且 本机不在线的情况下 就尝试转为桥接发送】
    // FIXME 【以后或许要实现】【第二阶段集群实现】时要修改以下在线状态判断为全局所有用户在线列表中的结果（而不只是本机）
    // 接收方不在本地MessageServer在线列表上（按照第一阶段的异构通信算法，直接发往APP服务端）
    if (config.im_bridge_enabled && !userProcessor.isOnline(p.to)) {

        if (socket) {
            logger.debug('[IMSDK-G-C2C-桥接↑] [E]%s(name=%s) 正在发送给 %s，消息：%s 【他在线吗？FALSE】，马上转入桥接发送↗ ！'
                , socket.id, socket.userId, p.to, JSON.stringify(p));
        }
        // 可以认为当socket为null时即为服务端发送的消息（只有C2C模式的消息发送时，才能取到发送者的socket句柄）
        else {
            logger.debug('[IMSDK-G-C2C-桥接↑] [E]服务端正在发送给 %s，消息：%s 【他在线吗？FALSE】，马上转入桥接发送↗ ！'
                , p.to, JSON.stringify(p));
        }

        // 如果此包需要QoS 且 之前已经成功被”收到“，则本次就不需要额外处理，只需再次发送伪应答，客户端重复发送的原因可能是因为之前的应答包丢包
        if(p.QoS && mbQoS4ReciveDaemon.hasRecieved(p.fp)) {
            // needDelegateACK = true;
            // 发送伪应答包，以便发送消息者（它自已其实不知道这条消息是被桥接处理的）知道已经送达
            // （因为不是真正的接收者应答，所以叫伪应答）发送伪应答的目的是保证在消息
            //   被离线处理或者桥接发送时，也能让发送者知道消息已被妥善送达（离线或桥接发送也同样是”送达“，只是非实时而已）
            replyRecievedBack(socket, p, null);
            logger.debug("[IMSDK-G-C2C-桥接↑] [E]【QoS_伪应答(hasRecieved!)_C2S】向%s发送%s的伪应答包成功,伪装from自：%s【第一阶段APP+WEB跨机通信算法】.", p.from, p.fp, p.to);
        }
        else {
            // 桥接发送代码
            imMQProvider.publishBridge(p, function (result) {
                // FIXME 更优化的实现：桥接没有发送成功怎么办？实时回一条不成功的提示？这样体验不会好一点？（实时不成功再离线回调）
                // publish成功了
                if (result) {
                    if (socket) {
                        logger.info('[IMSDK-G-C2C-桥接↑] [E]%s(name=%s) 发送给 %s 的消息：%s 已成功发出。【OK】'
                            , socket.id, socket.userId, p.to, JSON.stringify(p));
                    }
                    // 可以认为当socket为null时即为服务端发送的消息（只有C2C模式的消息发送时，才能取到发送者的socket句柄）
                    else {
                        logger.info('[IMSDK-G-C2C-桥接↑] [E]服务端 发送给 %s 的消息：%s 已成功发出。【OK】'
                            , p.to, JSON.stringify(p));
                    }
                }
                // publish失败
                else {
                    if (socket) {
                        logger.warn('[IMSDK-G-C2C-桥接↑] [E]%s(name=%s) 发送给 %s 的消息：%s 没有桥接发送成功【将通过离线回调通知应用层】。'
                            , socket.id, socket.userId, p.to, JSON.stringify(p));
                    }
                    // 可以认为当socket为null时即为服务端发送的消息（只有C2C模式的消息发送时，才能取到发送者的socket句柄）
                    else {
                        logger.warn('[IMSDK-G-C2C-桥接↑] [E]服务端 发送给 %s 的消息：%s 没有桥接发送成功【将通过离线回调通知应用层】。'
                            , p.to, JSON.stringify(p));
                    }

                    // @@ 通过MQ中间件桥接发送的C2C消息发送失败后的回调实现！（应用层可能需要做离线消息处理哦！）
                    if (arg_callBack_processC2COfflineMessage) {
                        arg_callBack_processC2COfflineMessage(p);
                    }
                    // @@ 如果没有指定arg_callBack_processC2COfflineMessage，则用默认的callBack_processC2COfflineMessage作为回调处理
                    else {
                        if (callBack_processC2COfflineMessage)
                            callBack_processC2COfflineMessage(p);
                    }
                }

                // 【如果该消息包有QoS机制】则将由则服务端代为发送一条伪应答包，因已桥接发送处理完成
                if(p.QoS){
                    // 发送伪应答包，以便发送消息者（它自已其实不知道这条消息是被桥接处理的）知道已经送达
                    // （因为不是真正的接收者应答，所以叫伪应答）发送伪应答的目的是保证在消息
                    //   被离线处理或者桥接发送时，也能让发送者知道消息已被妥善送达（离线或桥接发送也同样是”送达“，只是非实时而已）
                    replyRecievedBack(socket, p, null);
                    logger.debug("[IMSDK-G-C2C-桥接↑] [E]【QoS_伪应答_C2S】向%s发送%s的伪应答包成功,伪装from自：%s【第一阶段APP+WEB跨机通信算法】.", p.from, p.fp, p.to);
                }
            });
            // // 发送测试
            // imMQProvider.testPublish(p, function (result) {
            //     // FIXME 更优化的实现：桥接没有发送成功怎么办？实时回一条不成功的提示？这样体验不会好一点？（实时不成功再离线回调）
            //     // publish成功了
            //     if (result) {
            //         if (socket) {
            //             logger.info('[test-IMSDK-G-C2C-桥接↑] [E]%s(name=%s) 发送给 %s 的消息：%s 已成功发出。【OK】'
            //                 , socket.id, socket.userId, p.to, JSON.stringify(p));
            //         }
            //         // 可以认为当socket为null时即为服务端发送的消息（只有C2C模式的消息发送时，才能取到发送者的socket句柄）
            //         else {
            //             logger.info('[test-IMSDK-G-C2C-桥接↑] [E]服务端 发送给 %s 的消息：%s 已成功发出。【OK】'
            //                 , p.to, JSON.stringify(p));
            //         }
            //     }
            //     // publish失败
            //     else {
            //         if (socket) {
            //             logger.warn('[test-IMSDK-G-C2C-桥接↑] [E]%s(name=%s) 发送给 %s 的消息：%s 没有桥接发送成功【将通过离线回调通知应用层】。'
            //                 , socket.id, socket.userId, p.to, JSON.stringify(p));
            //         }
            //         // 可以认为当socket为null时即为服务端发送的消息（只有C2C模式的消息发送时，才能取到发送者的socket句柄）
            //         else {
            //             logger.warn('[test-IMSDK-G-C2C-桥接↑] [E]服务端 发送给 %s 的消息：%s 没有桥接发送成功【将通过离线回调通知应用层】。'
            //                 , p.to, JSON.stringify(p));
            //         }
            //     }
            // });
        }

        // 【【C2S[桥接]模式下的QoS机制2/4步：将收到的中转代发包存入QoS接收方暂存队列中（用于防QoS消息重复）】】
        // @see 客户端中的第1/4和第4/4步相关处理
        mbQoS4ReciveDaemon.addRecieved(p);
    }
    // ** 【本机在线或其它情况下则直接在本机范围内发送和处理】
    // 接收方在本MessageServer的在线列表中
    else{
        if(socket){
            logger.debug('[IMSDK-G-C2C] [E]%s(name=%s) 正在发送给 %s，消息：%s ，马上尝试进行本地直发-- ！'
                , socket.id, socket.userId, p.to, JSON.stringify(p));
        }
        // 可以认为当socket为null时即为服务端发送的消息（只有C2C模式的消息发送时，才能取到发送者的socket句柄）
        else{
            logger.debug('[IMSDK-G-C2C] [E]服务端 正在发送给 %s，消息：%s ，马上尝试进行本地直发-- ！'
                , p.to, JSON.stringify(p));
        }

        // 发送消息（此方法内的sendData实际上会通过回调处理在线和不在线的情况，只管调用就是了）
        var sendOK = sendDataLocal4OnlineOrOffline(socket, p, arg_callBack_processC2COfflineMessage);
        // 需要回复ACK应答
        if(p.QoS) {
            // 发送伪应答包，以便发送消息者（它自已其实不知道这条消息是被桥接处理的）知道已经送达
            replyRecievedBack(socket, p, null);
            logger.debug("[IMSDK-G-C2C] [E]【QoS_伪应答_C2S】向%s发送%s的伪应答包成功,伪装from自：%s.", p.from, p.fp, p.to);
        }

        return sendOK;
    }
}

/**
 *用方法用于服务端向客户端主动发起的数据之用，此方法封装了服务端发送
 * S2C消息的所有逻辑（包括当接收者不在本机在线列表时的桥接处理等，但不包括离线处理逻辑——请据本方法的
 * 返回值，在应用层决定如何进行离线处理）。
 * <p>
 * <b>提示：</b>本方法可用于应用层调用，从而实现服务端向客户端主动发送消息的能力（且支持跨机器的消息能力）。
 * <p>
 * <b>补充说明：</b>当没有开启与Web的消息互通时，调用本方法，相当于直接调用{@link sendDataLocal4OnlineOrOffline(p)}</font>
 *
 * @param p
 * @param arg_callBack_processC2COfflineMessage 非必须参数，用于指定消息没有在线发送成功时的离线消息回调处理，如果本参数为空则
 * 函数内将使用默认的callBack_processC2COfflineMessage作为离线消息的回调处理函数。【提示】：有些消息如果您不希望被离线存储（比如下线通知），
 * 则可以通过自定义本离线回调（比如让你的自写义回调只打出Log而不使用默认回调里的持久化到数据库等）来实现就行了！
 */
function sendDataGlobal_S2C(p, arg_callBack_processC2COfflineMessage){

    // ###### Bug FIX: 20170918 START
    // 如果回调函数arg_callBack_processC2COfflineMessage为空，则使用系统默认的
    // callBack_processC2COfflineMessage作为回调函数，否则使用用户自定义的回调函数
    if(arg_callBack_processC2COfflineMessage){
        // do nothing
    }
    else {
        arg_callBack_processC2COfflineMessage = callBack_processC2COfflineMessage;
    }
    // ###### Bug FIX: 20170918 END

    // ** 【已启用与APP端的互通 且 本机不在线的情况下 就尝试转为桥接发送】
    // FIXME 【以后或许要实现】【第二阶段集群实现】时要修改以下在线状态判断为全局所有用户在线列表中的结果（而不只是本机）
    // 接收方不在本地MessageServer在线列表上（按照第一阶段的异构通信算法，直接发往APP服务端）
    if (config.im_bridge_enabled && !userProcessor.isOnline(p.to)) {
        logger.debug('[IMSDK-G-S2C-桥接↑] [E]服务端 正在发送给 %s，消息：%s 【他在线吗？FALSE】，马上转入桥接发送↗ ！', p.to, JSON.stringify(p));

        // 桥接发送代码
        imMQProvider.publishBridge(p, function (result) {
            // FIXME 更优化的实现：桥接没有发送成功怎么办？实时回一条不成功的提示？这样体验不会好一点？（实时不成功再离线回调）
            // publish成功了
            if (result) {
                logger.info('[IMSDK-G-S2C-桥接↑] [E]服务端 发送给 %s 的消息：%s 已成功发出。【OK】', p.to, JSON.stringify(p));
            }
            // publish失败
            else {

                logger.warn('[IMSDK-G-S2C-桥接↑] [E]服务端 发送给 %s 的消息：%s 没有桥接发送成功【将通过离线回调通知应用层】。', p.to, JSON.stringify(p));

                // @@ 通过MQ中间件桥接发送的C2C消息发送失败后的回调实现！（应用层可能需要做离线消息处理哦！）
                if (arg_callBack_processC2COfflineMessage) {
                    arg_callBack_processC2COfflineMessage(p);
                }
                // @@ 如果没有指定arg_callBack_processC2COfflineMessage，则用默认的callBack_processC2COfflineMessage作为回调处理
                else {
                    if (callBack_processC2COfflineMessage)
                        callBack_processC2COfflineMessage(p);
                }
            }
        });
    }
    // ** 【本机在线或其它情况下则直接在本机范围内发送和处理】
    // 接收方在本MessageServer的在线列表中
    else{
        logger.debug('[IMSDK-G-S2C] [E]服务端 正在发送给 %s，消息：%s ，马上尝试进行本地直发-- ！', p.to, JSON.stringify(p));

        // 发送消息（此方法内的sendData实际上会通过回调处理在线和不在线的情况，只管调用就是了）
        var sendOK = sendDataLocal4OnlineOrOffline(null, p, arg_callBack_processC2COfflineMessage);
        return sendOK;
    }
}

